def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h)
                if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w)
                if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    # Tile bounds exclude the separator lines.
    rb = [0] + sep_rows + [h]
    cb = [0] + sep_cols + [w]
    tiles = [[(rb[i] if i == 0 else rb[i] + 1, rb[i + 1],
               cb[j] if j == 0 else cb[j] + 1, cb[j + 1])
              for j in range(len(cb) - 1)]
             for i in range(len(rb) - 1)]

    out = [row[:] for row in grid]

    def pattern(box, color):
        r0, r1, c0, c1 = box
        return {(r - r0, c - c0) for r in range(r0, r1)
                for c in range(c0, c1) if grid[r][c] == color}

    for color in range(1, 10):
        best_boundary, best_score = None, 0

        # Find the panel boundary around which this color already shows
        # horizontal mirror symmetry.
        for boundary in range(len(cb) - 2):
            score = 0
            for row in range(len(rb) - 1):
                left = pattern(tiles[row][boundary], color)
                right = pattern(tiles[row][boundary + 1], color)
                if not left or not right:
                    continue
                lh, lw = tiles[row][boundary][1] - tiles[row][boundary][0], \
                         tiles[row][boundary][3] - tiles[row][boundary][2]
                rh, rw = tiles[row][boundary + 1][1] - tiles[row][boundary + 1][0], \
                         tiles[row][boundary + 1][3] - tiles[row][boundary + 1][2]
                width, height = min(lw, rw), min(lh, rh)
                reflected = {(r, width - 1 - c) for r, c in left
                             if r < height and c < width}
                right_clipped = {(r, c) for r, c in right
                                 if r < height and c < width}
                if reflected == right_clipped:
                    score += 1
            if score > best_score:
                best_score, best_boundary = score, boundary

        if best_boundary is None:
            continue

        for row in range(len(rb) - 1):
            left_box = tiles[row][best_boundary]
            right_box = tiles[row][best_boundary + 1]
            left = pattern(left_box, color)
            right = pattern(right_box, color)
            if bool(left) == bool(right):
                continue

            source, target = (left_box, right_box) if left else (right_box, left_box)
            r0, r1, c0, c1 = source
            tr0, tr1, tc0, tc1 = target
            height = min(r1 - r0, tr1 - tr0)
            width = min(c1 - c0, tc1 - tc0)

            for r in range(height):
                for c in range(width):
                    if grid[r0 + r][c0 + c] == color:
                        rr, cc = tr0 + r, tc0 + width - 1 - c
                        if out[rr][cc] == 0:
                            out[rr][cc] = color

    return out
